using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.AspNetCore.Mvc.ModelBinding.Validation;

namespace NexusCommunication.Models;

/// <summary>
/// A customer of Nexus Communication. CustomerCode is the 10-digit unique id from the
/// existing-scenario description (separate from the 16-char connection AccountId).
/// </summary>
public class Customer : IEntity, IValidatableObject
{
    public int Id { get; set; }

    /// <summary>Unique 10-digit customer code generated by the server.</summary>
    [BindNever, ValidateNever]
    [MaxLength(10)]
    [Display(Name = "Customer Code")]
    public string CustomerCode { get; set; } = "";

    [Required(ErrorMessage = "Customer name is required.")]
    [MinLength(2, ErrorMessage = "Customer name must be at least 2 characters long.")]
    [RegularExpression(@"^[A-Za-z]+( [A-Za-z]+)*$", ErrorMessage = "Customer name can contain only letters and single spaces (no digits or symbols).")]
    [MaxLength(150, ErrorMessage = "Customer name cannot be longer than 150 characters.")]
    [Display(Name = "Customer Name")]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Contact number is required.")]
    [RegularExpression(@"^\+?[0-9][0-9\s\-()]{6,19}$",
        ErrorMessage = "Enter a valid phone number (7 to 20 digits; spaces, - and ( ) are allowed; may start with +).")]
    [MaxLength(30)]
    [Display(Name = "Contact Number")]
    public string Phone { get; set; } = "";

    [EmailAddress(ErrorMessage = "Enter a valid e-mail address.")]
    [MaxLength(150, ErrorMessage = "E-mail cannot be longer than 150 characters.")]
    [Display(Name = "E-mail")]
    public string? Email { get; set; }

    [MaxLength(300, ErrorMessage = "Address cannot be longer than 300 characters.")]
    public string? Address { get; set; }

    public int? CityId { get; set; }
    public City? City { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public bool IsActive { get; set; } = true;

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (string.IsNullOrWhiteSpace(Email)) yield return new ValidationResult("E-mail is required (it is the login of the customer portal).", new[] { nameof(Email) });
        if (string.IsNullOrWhiteSpace(Address)) yield return new ValidationResult("Address is required.", new[] { nameof(Address) });
    }
}
